<?php

namespace App\Http\Controllers;

use Illuminate\Http\Exceptions\HttpResponseException;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use App\Services\OrdersCounterService;
use Throwable;

class OrderConfigurationController extends Controller
{
    private function fail(string $message): never { throw new HttpResponseException(response()->json(['error'=>$message],400)); }
    private function userId(Request $r): int
    {
        $id=DB::table('users')->where('email',$r->attributes->get('jwt_subject'))->value('id');
        if (!$id) $this->fail('User not found'); return (int)$id;
    }
    private function run(callable $f) { try { return $f(); } catch (HttpResponseException $e) { throw $e; } catch (Throwable $e) { $this->fail($e->getMessage() ?: 'Bad request'); } }
    private function requiredText(mixed $v,string $field): string { if (!is_string($v)||trim($v)==='') $this->fail("$field is required"); return trim($v); }
    // These mirror the controller's Java Map casts: null remains null and numeric/boolean JSON types are required.
    private function javaString(mixed $v): ?string { if($v===null)return null; if(is_bool($v))return $v?'true':'false'; if(is_scalar($v))return (string)$v; $this->fail('Invalid text value'); }
    private function javaNumber(mixed $v,string $field): ?int { if($v===null)return null; if(!is_int($v)&&!is_float($v))$this->fail("$field must be a number"); return (int)$v; }
    private function javaBoolean(mixed $v,string $field): ?bool { if($v===null)return null; if(!is_bool($v))$this->fail("$field must be a boolean"); return $v; }
    private function dto(object $r,array $fields): array
    {
        $out=['id'=>(int)$r->id]; foreach($fields as $key=>$col) $out[$key]=in_array($key,['required','allowsCustom','active'],true)?(bool)$r->$col:$r->$col;
        foreach(['createdAt'=>'created_at','updatedAt'=>'updated_at'] as $k=>$col) if(property_exists($r,$col)) $out[$k]=str_replace(' ','T',$r->$col);
        return $out;
    }
    private function groupDto(object $r): array { return $this->dto($r,['userId'=>'user_id','name'=>'name','inputType'=>'input_type','required'=>'required','sequence'=>'sequence','active'=>'active']); }
    private function valueDto(object $r): array { return $this->dto($r,['userId'=>'user_id','groupId'=>'group_id','value'=>'value','allowsCustom'=>'allows_custom','sequence'=>'sequence','active'=>'active']); }
    private function flowDto(object $r): array { return $this->dto($r,['userId'=>'user_id','name'=>'name','rootGroupId'=>'root_group_id','active'=>'active']); }
    private function edgeDto(object $r): array { return $this->dto($r,['userId'=>'user_id','flowId'=>'flow_id','fromGroupId'=>'from_group_id','selectedValueId'=>'selected_value_id','toGroupId'=>'to_group_id','sequence'=>'sequence']); }
    private function group(int $u,int $id): object { $r=DB::table('order_option_groups')->where(['id'=>$id,'user_id'=>$u,'active'=>true])->first(); if(!$r)$this->fail('Option group not found'); return $r; }
    private function value(int $u,int $id): object { $r=DB::table('order_option_values')->where(['id'=>$id,'user_id'=>$u,'active'=>true])->first(); if(!$r)$this->fail('Option value not found'); return $r; }
    private function flow(int $u,int $id): object { $r=DB::table('order_flows')->where(['id'=>$id,'user_id'=>$u,'active'=>true])->first(); if(!$r)$this->fail('Order flow not found'); return $r; }
    private function unique(string $table,int $u,string $field,string $value,?int $group=null,?int $except=null): void
    {
        $q=DB::table($table)->where('user_id',$u)->where('active',true)->whereRaw('LOWER('.$field.') = ?',[Str::lower($value)]);
        if($group!==null)$q->where('group_id',$group); if($except!==null)$q->where('id','!=',$except);
        if($q->exists())$this->fail($table==='order_flows'?'Order flow already exists':($table==='order_option_groups'?'Option group already exists':'Option value already exists in this group'));
    }
    public function groups(Request $r) { return $this->run(function()use($r){$u=$this->userId($r);$rows=DB::table('order_option_groups')->where(['user_id'=>$u,'active'=>true])->orderBy('sequence')->orderBy('name')->get()->map(fn($x)=>$this->groupDto($x));return ['groups'=>$rows];}); }
    public function createGroup(Request $r) { return $this->run(function()use($r){$u=$this->userId($r);$name=$this->requiredText($this->javaString($r->input('name')),'name');$rawType=$this->javaString($r->input('inputType'));$type=strtoupper(trim(($rawType===null||trim($rawType)==='')?'SELECT':$rawType));if(!in_array($type,['SELECT','TEXT','NUMBER'],true))$this->fail('inputType must be SELECT, TEXT, or NUMBER');$required=$this->javaBoolean($r->input('required'),'required');$sequence=$this->javaNumber($r->input('sequence'),'sequence');$this->unique('order_option_groups',$u,'name',$name);$id=DB::table('order_option_groups')->insertGetId(['user_id'=>$u,'name'=>$name,'input_type'=>$type,'required'=>$required??true,'sequence'=>$sequence??0,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Option group created successfully','group'=>$this->groupDto(DB::table('order_option_groups')->find($id))],201);}); }
    public function updateGroup(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$g=$this->group($u,$id);$d=['updated_at'=>now()];$name=$this->javaString($r->input('name'));if($name!==null&&trim($name)!==''){$n=trim($name);if(strcasecmp($n,$g->name)!==0){$this->unique('order_option_groups',$u,'name',$n,null,$id);$d['name']=$n;}}$input=$this->javaString($r->input('inputType'));if($input!==null){$t=strtoupper(trim($input));if(!in_array($t,['SELECT','TEXT','NUMBER'],true))$this->fail('inputType must be SELECT, TEXT, or NUMBER');$d['input_type']=$t;}$required=$this->javaBoolean($r->input('required'),'required');$sequence=$this->javaNumber($r->input('sequence'),'sequence');if($required!==null)$d['required']=$required;if($sequence!==null)$d['sequence']=$sequence;DB::table('order_option_groups')->where('id',$id)->update($d);return ['message'=>'Option group updated successfully','group'=>$this->groupDto(DB::table('order_option_groups')->find($id))];}); }
    public function deleteGroup(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$this->group($u,$id);DB::table('order_option_groups')->where('id',$id)->update(['active'=>false,'updated_at'=>now()]);return ['message'=>'Option group deleted successfully'];}); }
    public function values(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$this->group($u,$id);return ['values'=>DB::table('order_option_values')->where(['user_id'=>$u,'group_id'=>$id,'active'=>true])->orderBy('sequence')->orderBy('value')->get()->map(fn($x)=>$this->valueDto($x))];}); }
    public function createValue(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$this->group($u,$id);$v=$this->requiredText($this->javaString($r->input('value')),'value');$allows=$this->javaBoolean($r->input('allowsCustom'),'allowsCustom');$sequence=$this->javaNumber($r->input('sequence'),'sequence');$this->unique('order_option_values',$u,'value',$v,$id);$new=DB::table('order_option_values')->insertGetId(['user_id'=>$u,'group_id'=>$id,'value'=>$v,'allows_custom'=>$allows??false,'sequence'=>$sequence??0,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Option value created successfully','value'=>$this->valueDto(DB::table('order_option_values')->find($new))],201);}); }
    public function updateValue(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$v=$this->value($u,$id);$d=['updated_at'=>now()];$text=$this->javaString($r->input('value'));if($text!==null&&trim($text)!==''){$s=trim($text);if(strcasecmp($s,$v->value)!==0){$this->unique('order_option_values',$u,'value',$s,(int)$v->group_id,$id);$d['value']=$s;}}$allows=$this->javaBoolean($r->input('allowsCustom'),'allowsCustom');$sequence=$this->javaNumber($r->input('sequence'),'sequence');if($allows!==null)$d['allows_custom']=$allows;if($sequence!==null)$d['sequence']=$sequence;DB::table('order_option_values')->where('id',$id)->update($d);return ['message'=>'Option value updated successfully','value'=>$this->valueDto(DB::table('order_option_values')->find($id))];}); }
    public function deleteValue(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$this->value($u,$id);DB::table('order_option_values')->where('id',$id)->update(['active'=>false,'updated_at'=>now()]);return ['message'=>'Option value deleted successfully'];}); }
    public function flows(Request $r) { return $this->run(function()use($r){$u=$this->userId($r);return ['flows'=>DB::table('order_flows')->where(['user_id'=>$u,'active'=>true])->orderBy('name')->get()->map(fn($x)=>$this->flowDto($x))];}); }
    public function createFlow(Request $r) { return $this->run(function()use($r){$u=$this->userId($r);$n=$this->requiredText($this->javaString($r->input('name')),'name');$root=$this->javaNumber($r->input('rootGroupId'),'rootGroupId');if($root===null)$this->fail('rootGroupId is required');$this->group($u,$root);$this->unique('order_flows',$u,'name',$n);$id=DB::table('order_flows')->insertGetId(['user_id'=>$u,'name'=>$n,'root_group_id'=>$root,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Order flow created successfully','flow'=>$this->flowDto(DB::table('order_flows')->find($id))],201);}); }
    public function showFlow(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$this->flow($u,$id);$edges=DB::table('order_flow_edges')->where(['user_id'=>$u,'flow_id'=>$id])->orderBy('sequence')->orderBy('id')->get()->map(fn($x)=>$this->edgeDto($x));return ['flow'=>$this->flowDto($this->flow($u,$id)),'edges'=>$edges];}); }
    public function updateFlow(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$f=$this->flow($u,$id);$d=['updated_at'=>now()];$name=$this->javaString($r->input('name'));if($name!==null&&trim($name)!==''){$n=trim($name);if(strcasecmp($n,$f->name)!==0){$this->unique('order_flows',$u,'name',$n,null,$id);$d['name']=$n;}}$root=$this->javaNumber($r->input('rootGroupId'),'rootGroupId');if($root!==null){$this->group($u,$root);$d['root_group_id']=$root;}DB::table('order_flows')->where('id',$id)->update($d);return ['message'=>'Order flow updated successfully','flow'=>$this->flowDto(DB::table('order_flows')->find($id))];}); }
    public function deleteFlow(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$this->flow($u,$id);DB::table('order_flows')->where('id',$id)->update(['active'=>false,'updated_at'=>now()]);return ['message'=>'Order flow deleted successfully'];}); }
    public function edges(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$this->flow($u,$id);return ['edges'=>DB::table('order_flow_edges')->where(['user_id'=>$u,'flow_id'=>$id])->orderBy('sequence')->orderBy('id')->get()->map(fn($x)=>$this->edgeDto($x))];}); }
    public function createEdge(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$this->flow($u,$id);$from=$this->javaNumber($r->input('fromGroupId'),'fromGroupId');$sel=$this->javaNumber($r->input('selectedValueId'),'selectedValueId');$to=$this->javaNumber($r->input('toGroupId'),'toGroupId');if($from===null||$sel===null||$to===null)$this->fail('fromGroupId, selectedValueId, and toGroupId are required');$sequence=$this->javaNumber($r->input('sequence'),'sequence')??0;$this->group($u,$from);$v=$this->value($u,$sel);if((int)$v->group_id!==$from)$this->fail('selectedValueId must belong to fromGroupId');$this->group($u,$to);if(DB::table('order_flow_edges')->where(['user_id'=>$u,'flow_id'=>$id,'from_group_id'=>$from,'selected_value_id'=>$sel])->exists())$this->fail('A next question is already configured for this selected value');$edge=DB::table('order_flow_edges')->insertGetId(['user_id'=>$u,'flow_id'=>$id,'from_group_id'=>$from,'selected_value_id'=>$sel,'to_group_id'=>$to,'sequence'=>$sequence,'created_at'=>now()]);return response()->json(['message'=>'Order flow edge created successfully','edge'=>$this->edgeDto(DB::table('order_flow_edges')->find($edge))],201);}); }
    public function deleteEdge(Request $r,int $id,int $eid) { return $this->run(function()use($r,$id,$eid){$u=$this->userId($r);$this->flow($u,$id);if(!DB::table('order_flow_edges')->where(['id'=>$eid,'user_id'=>$u,'flow_id'=>$id])->exists())$this->fail('Order flow edge not found');DB::table('order_flow_edges')->where('id',$eid)->delete();return ['message'=>'Order flow edge deleted successfully'];}); }
    private function question(int $u,int $gid): array { $g=$this->group($u,$gid);$vals=DB::table('order_option_values')->where(['user_id'=>$u,'group_id'=>$gid,'active'=>true])->orderBy('sequence')->orderBy('value')->get()->map(fn($x)=>$this->valueDto($x));return ['finished'=>false,'groupId'=>(int)$g->id,'label'=>$g->name,'inputType'=>$g->input_type,'required'=>(bool)$g->required,'values'=>$vals]; }
    public function start(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);return $this->question($u,(int)$this->flow($u,$id)->root_group_id);}); }
    public function next(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->userId($r);$this->flow($u,$id);$from=$this->javaNumber($r->input('currentGroupId'),'currentGroupId');$sel=$this->javaNumber($r->input('selectedValueId'),'selectedValueId');if($from===null||$sel===null)$this->fail('currentGroupId and selectedValueId are required');$this->group($u,$from);$v=$this->value($u,$sel);if((int)$v->group_id!==$from)$this->fail('selectedValueId must belong to currentGroupId');$e=DB::table('order_flow_edges')->where(['user_id'=>$u,'flow_id'=>$id,'from_group_id'=>$from,'selected_value_id'=>$sel])->first();return $e?$this->question($u,(int)$e->to_group_id):['finished'=>true];}); }
    public function counts(Request $r, OrdersCounterService $counters) { return $this->run(function()use($r,$counters){return $counters->getCounts($this->userId($r));}); }
}
